<?php
declare(strict_types=1);require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireOwner();$id=(int)($_GET['id']??0);$projectId=(int)($_GET['project_id']??0);$status=(string)($_GET['status']??'');$agent=(string)($_GET['agent']??'');AdminUi::header($id?'تفاصيل المهمة':'المهام','tasks');echo AdminUi::flash();if($id){$t=TaskService::get($id);$ev=db()->prepare('SELECT * FROM task_events WHERE task_id=? ORDER BY id DESC LIMIT 100');$ev->execute([$id]);$rv=db()->prepare('SELECT * FROM reviews WHERE task_id=? OR task_id IN (SELECT id FROM tasks WHERE parent_task_id=?) ORDER BY id DESC');$rv->execute([$id,$id]);$deps=db()->prepare("SELECT d.depends_on_task_id,t.title,t.status FROM task_dependencies d JOIN tasks t ON t.id=d.depends_on_task_id WHERE d.task_id=?");$deps->execute([$id]);$children=db()->prepare("SELECT t.*,a.display_name agent_name FROM tasks t LEFT JOIN agents a ON a.id=t.assigned_agent_id WHERE t.parent_task_id=? ORDER BY t.id");$children->execute([$id]);$agents=AgentService::all();?>
<div class="grid"><section class="card span-8"><div class="card-title"><div><h2>#<?=$id?> — <?=e($t['title'])?></h2><span class="muted small">رقم داخلي <?=e($t['uid'])?></span></div><?=AdminUi::badge($t['status'])?></div><dl class="kvs"><dt>المشروع</dt><dd><?=$t['project_id']?'<a class="link" href="projects.php?id='.(int)$t['project_id'].'">'.e($t['project_name']).'</a>':'—'?></dd><dt>الوكيل</dt><dd><?=e($t['agent_name']?:'—')?></dd><dt>طلبها مين</dt><dd><?=e($t['requested_by_type'].' '.($t['requested_by_id']?:''))?></dd><dt>الأولوية</dt><dd><?=e(AdminUi::priority($t['priority']))?></dd><dt>حالة المراجعة</dt><dd><?=AdminUi::badge($t['review_status'])?></dd><dt>المحاولة</dt><dd><?=(int)$t['current_attempt']?>/<?=(int)$t['max_attempts']?></dd><dt>بدأت</dt><dd><?=e(AdminUi::date($t['started_at']))?></dd><dt>خلصت</dt><dd><?=e(AdminUi::date($t['completed_at']))?></dd></dl><h3 style="font-size:14px">المطلوب</h3><div class="pre"><?=e($t['description'])?></div></section><section class="card span-4"><div class="card-title"><h2>تحكم رامي</h2></div><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="task_reassign"><input type="hidden" name="task_id" value="<?=$id?>"><div class="field"><label>نقل المهمة لوكيل</label><select name="agent_slug"><?php foreach($agents as $a):?><option value="<?=e($a['slug'])?>" <?=$t['agent_slug']===$a['slug']?'selected':''?>><?=e($a['display_name'])?></option><?php endforeach?></select></div><button class="btn secondary">إعادة تعيين</button></form><div class="actions" style="margin-top:14px"><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="task_retry"><input type="hidden" name="task_id" value="<?=$id?>"><button class="btn">إعادة تشغيل</button></form><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="task_send_emad"><input type="hidden" name="task_id" value="<?=$id?>"><button class="btn secondary">شغّل عماد للمراجعة</button></form><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="task_cancel"><input type="hidden" name="task_id" value="<?=$id?>"><button class="btn danger" data-confirm="إلغاء هذه المهمة؟">إلغاء</button></form><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="task_rollback"><input type="hidden" name="task_id" value="<?=$id?>"><button class="btn danger" data-confirm="إرجاع تغييرات الملفات المسجلة لهذه المهمة؟ إذا كانت المهمة عدلت قاعدة بيانات سيظهر تنبيه بأن استرجاعها يحتاج إجراء مستقل.">رجّع النسخة</button></form></div><hr style="border:0;border-top:1px solid var(--line);margin:16px 0"><b class="small">سياق المهمة</b><div class="pre mono" style="margin-top:8px"><?=e($t['context_json']?:'{}')?></div></section>
<section class="card span-6"><div class="card-title"><h2>المهام المرتبطة والفرعية</h2></div><?php foreach($deps->fetchAll() as $d):?><div class="mini-item"><div class="grow"><b>يعتمد على #<?=$d['depends_on_task_id']?> <?=e($d['title'])?></b></div><?=AdminUi::badge($d['status'])?></div><?php endforeach?><?php foreach($children->fetchAll() as $c):?><div class="mini-item"><div class="grow"><b><a class="link" href="tasks.php?id=<?=$c['id']?>">مهمة فرعية #<?=$c['id']?> <?=e($c['title'])?></a></b><small><?=e($c['agent_name']?:'—')?></small></div><?=AdminUi::badge($c['status'])?></div><?php endforeach?></section>
<section class="card span-6"><div class="card-title"><h2>تقارير عماد</h2></div><?php $rr=$rv->fetchAll();if(!$rr):?><?=AdminUi::empty('لا يوجد تقرير مراجعة بعد.')?><?php else:foreach($rr as $r):?><a class="mini-item" href="qa.php?id=<?=$r['id']?>" style="text-decoration:none;color:inherit"><div class="grow"><b>مراجعة #<?=$r['id']?></b><small><?=e(pb_substr($r['summary'],0,260))?></small></div><?=AdminUi::badge($r['status'])?></a><?php endforeach;endif?></section>
<section class="card span-12"><div class="card-title"><h2>تاريخ تحركات المهمة</h2></div><div class="timeline"><?php foreach($ev->fetchAll() as $x):?><div class="timeline-item"><time><?=e(AdminUi::date($x['created_at']))?></time><div><b><?=e(AdminUi::label($x['event_type']))?></b> <span class="muted small"><?=e(AdminUi::label($x['from_status']?:'').' ← '.AdminUi::label($x['to_status']?:''))?></span><div class="muted small"><?=e($x['details_json']?:'')?></div></div></div><?php endforeach?></div></section></div>
<?php }else{$where=[];$args=[];if($projectId){$where[]='t.project_id=?';$args[]=$projectId;}if($status&&in_array($status,['new','queued','assigned','working','waiting','blocked','needs_review','review_failed','needs_fix','retesting','approved','completed','cancelled','failed'],true)){$where[]='t.status=?';$args[]=$status;}if($agent!==''){$where[]='a.slug=?';$args[]=$agent;}$sql="SELECT t.*,a.display_name agent_name,a.slug agent_slug,p.name project_name FROM tasks t LEFT JOIN agents a ON a.id=t.assigned_agent_id LEFT JOIN projects p ON p.id=t.project_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY t.id DESC LIMIT 400";$q=db()->prepare($sql);$q->execute($args);$rows=$q->fetchAll();$agents=AgentService::all();?>
<div class="toolbar"><form method="get"><select name="status"><option value="">كل الحالات</option><?php foreach(['queued','assigned','working','waiting','blocked','needs_review','needs_fix','retesting','completed','failed','cancelled'] as $x):?><option value="<?=e($x)?>" <?=$status===$x?'selected':''?>><?=e(AdminUi::label($x))?></option><?php endforeach?></select><select name="agent"><option value="">كل الوكلاء</option><?php foreach($agents as $a):?><option value="<?=e($a['slug'])?>" <?=$agent===$a['slug']?'selected':''?>><?=e($a['display_name'])?></option><?php endforeach?></select><button class="btn secondary">فلترة</button></form></div><section class="card"><div class="card-title"><div><h2>دورة المهام</h2><span class="muted small">جديدة ← في الطابور ← شغالة ← مراجعة عماد ← إصلاح وإعادة اختبار ← اعتماد ← خلصت</span></div></div><div class="table-wrap"><table><thead><tr><th>#</th><th>المهمة</th><th>المشروع</th><th>الوكيل</th><th>الأولوية</th><th>الحالة</th><th>المراجعة</th><th>المحاولة</th><th>آخر تحديث</th></tr></thead><tbody><?php foreach($rows as $t):?><tr><td><a href="tasks.php?id=<?=$t['id']?>">#<?=$t['id']?></a></td><td><?=e($t['title'])?></td><td><?=e($t['project_name']?:'—')?></td><td><?=e($t['agent_name']?:'—')?></td><td><?=e(AdminUi::priority($t['priority']))?></td><td><?=AdminUi::badge($t['status'])?></td><td><?=AdminUi::badge($t['review_status'])?></td><td><?=(int)$t['current_attempt']?>/<?=(int)$t['max_attempts']?></td><td><?=e(AdminUi::date($t['updated_at']))?></td></tr><?php endforeach?></tbody></table></div></section><?php }AdminUi::footer();
